package com.fixmyphone.device
import android.content.Context; import android.media.AudioManager; import com.facebook.react.bridge.*
class VolumeModule(private val ctx:ReactApplicationContext):ReactContextBaseJavaModule(ctx){override fun getName()="Volume";@ReactMethod fun get(p:Promise){val a=ctx.getSystemService(Context.AUDIO_SERVICE) as AudioManager;val r=Arguments.createMap();r.putInt("level",a.getStreamVolume(AudioManager.STREAM_MUSIC));r.putInt("max",a.getStreamMaxVolume(AudioManager.STREAM_MUSIC));p.resolve(r)};@ReactMethod fun set(level:Int,p:Promise){val a=ctx.getSystemService(Context.AUDIO_SERVICE) as AudioManager;val max=a.getStreamMaxVolume(AudioManager.STREAM_MUSIC);a.setStreamVolume(AudioManager.STREAM_MUSIC,(max*level.coerceIn(0,100))/100,0);p.resolve(true)}}
